Best Practice: JWT in HttpOnly Cookies
Combine the best of both! Send the JWT as an HttpOnly, Secure cookie.
```javascript
// Server issuing JWT in HttpOnly cookie
const jwt = require('jsonwebtoken');

app.post('/api/login', async (req, res) => {
  const { email, password } = req.body;
  const user = await verifyCredentials(email, password);

if (user) {
    // Generate token
    const token = jwt.sign({ userId: user.id }, process.env.JWT_SECRET, { expiresIn: '15m' });

// Set HttpOnly cookie
    res.cookie('token', token, {
      httpOnly: true, // Not accessible via JavaScript (prevents XSS)
      secure: process.env.NODE_ENV === 'production', // HTTPS only
      sameSite: 'strict', // Prevents CSRF
      maxAge: 15 * 60 * 1000 // 15 mins
    });

res.json({ message: 'Logged in' });
  }
});

// Middleware to verify
const authenticateToken = (req, res, next) => {
  const token = req.cookies.token; // requires cookie-parser middleware
  if (!token) return res.sendStatus(401);

jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
    if (err) return res.sendStatus(403);
    req.user = decoded; // { userId: 123 }
    next();
  });
};
```
Refresh Tokens: Because access tokens should be short-lived (15m), a long-lived Refresh Token (7 days) is kept in the database and sent as a separate HttpOnly cookie to get new access tokens.

