class MainActivity : AppCompatActivity() {

// Register launchers in onCreate or as class properties (NOT in onClick!)
    private val requestCameraPermission = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        when {
            isGranted -> openCamera()
            shouldShowRequestPermissionRationale(Manifest.permission.CAMERA) -> {
                // User denied but can ask again — show explanation
                showRationale("Camera is needed to take profile photos") {
                    requestCameraPermission.launch(Manifest.permission.CAMERA)
                }
            }
            else -> {
                // User denied permanently ("Don't ask again")
                showSettingsDialog("Please enable Camera in app settings")
            }
        }
    }

private val requestMultiplePermissions = registerForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions()
    ) { permissions ->
        val cameraGranted = permissions[Manifest.permission.CAMERA] == true
        val micGranted = permissions[Manifest.permission.RECORD_AUDIO] == true

when {
            cameraGranted && micGranted -> startVideoCall()
            !cameraGranted -> showError("Camera permission denied")
            !micGranted -> showError("Microphone permission denied")
        }
    }

private fun checkAndRequestCamera() {
        when {
            ContextCompat.checkSelfPermission(this, CAMERA) == PERMISSION_GRANTED -> {
                openCamera()  // Already granted
            }
            shouldShowRequestPermissionRationale(CAMERA) -> {
                // Show rationale dialog, then request
                showRationale("Camera needed for profile photo") {
                    requestCameraPermission.launch(CAMERA)
                }
            }
            else -> {
                requestCameraPermission.launch(CAMERA)
            }
        }
    }
}
